CREATE TABLE users (id BIGINT PRIMARY KEY AUTO_INCREMENT, username VARCHAR(30) NOT NULL UNIQUE, email VARCHAR(255) NOT NULL UNIQUE, password_hash VARCHAR(255) NOT NULL, bio VARCHAR(500), avatar_url VARCHAR(500), karma INT NOT NULL DEFAULT 0, status VARCHAR(20) NOT NULL DEFAULT 'ACTIVE', created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
CREATE TABLE roles (id BIGINT PRIMARY KEY AUTO_INCREMENT, name VARCHAR(30) NOT NULL UNIQUE);
INSERT INTO roles(name) VALUES ('USER'),('MODERATOR'),('ADMIN');
CREATE TABLE user_roles (user_id BIGINT NOT NULL, role_id BIGINT NOT NULL, PRIMARY KEY(user_id,role_id), FOREIGN KEY(user_id) REFERENCES users(id), FOREIGN KEY(role_id) REFERENCES roles(id));
CREATE TABLE refresh_tokens (id BIGINT PRIMARY KEY AUTO_INCREMENT, token VARCHAR(255) NOT NULL UNIQUE, user_id BIGINT NOT NULL, expires_at TIMESTAMP NOT NULL, revoked BOOLEAN NOT NULL DEFAULT FALSE, FOREIGN KEY(user_id) REFERENCES users(id));
CREATE TABLE communities (id BIGINT PRIMARY KEY AUTO_INCREMENT, name VARCHAR(50) NOT NULL UNIQUE, description VARCHAR(1000) NOT NULL, visibility VARCHAR(20) NOT NULL DEFAULT 'PUBLIC', icon_url VARCHAR(500), banner_url VARCHAR(500), created_by BIGINT NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(created_by) REFERENCES users(id));
CREATE TABLE community_members (community_id BIGINT NOT NULL, user_id BIGINT NOT NULL, member_role VARCHAR(20) NOT NULL DEFAULT 'MEMBER', joined_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY(community_id,user_id), FOREIGN KEY(community_id) REFERENCES communities(id), FOREIGN KEY(user_id) REFERENCES users(id));
CREATE TABLE community_rules (id BIGINT PRIMARY KEY AUTO_INCREMENT, community_id BIGINT NOT NULL, rule_text VARCHAR(500) NOT NULL, position INT NOT NULL, FOREIGN KEY(community_id) REFERENCES communities(id));
CREATE TABLE posts (id BIGINT PRIMARY KEY AUTO_INCREMENT, community_id BIGINT NOT NULL, author_id BIGINT NOT NULL, title VARCHAR(300) NOT NULL, content TEXT, post_type VARCHAR(20) NOT NULL, external_url VARCHAR(1000), score INT NOT NULL DEFAULT 0, comment_count INT NOT NULL DEFAULT 0, status VARCHAR(20) NOT NULL DEFAULT 'ACTIVE', locked BOOLEAN NOT NULL DEFAULT FALSE, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, FOREIGN KEY(community_id) REFERENCES communities(id), FOREIGN KEY(author_id) REFERENCES users(id), INDEX idx_posts_feed(community_id,created_at), INDEX idx_posts_author(author_id));
CREATE TABLE comments (id BIGINT PRIMARY KEY AUTO_INCREMENT, post_id BIGINT NOT NULL, parent_comment_id BIGINT NULL, author_id BIGINT NOT NULL, content TEXT NOT NULL, score INT NOT NULL DEFAULT 0, status VARCHAR(20) NOT NULL DEFAULT 'ACTIVE', locked BOOLEAN NOT NULL DEFAULT FALSE, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, FOREIGN KEY(post_id) REFERENCES posts(id), FOREIGN KEY(parent_comment_id) REFERENCES comments(id), FOREIGN KEY(author_id) REFERENCES users(id), INDEX idx_comments_post(post_id,created_at));
CREATE TABLE post_votes (user_id BIGINT NOT NULL, post_id BIGINT NOT NULL, value TINYINT NOT NULL, PRIMARY KEY(user_id,post_id), FOREIGN KEY(user_id) REFERENCES users(id), FOREIGN KEY(post_id) REFERENCES posts(id));
CREATE TABLE comment_votes (user_id BIGINT NOT NULL, comment_id BIGINT NOT NULL, value TINYINT NOT NULL, PRIMARY KEY(user_id,comment_id), FOREIGN KEY(user_id) REFERENCES users(id), FOREIGN KEY(comment_id) REFERENCES comments(id));
CREATE TABLE saved_posts (user_id BIGINT NOT NULL, post_id BIGINT NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY(user_id,post_id), FOREIGN KEY(user_id) REFERENCES users(id), FOREIGN KEY(post_id) REFERENCES posts(id));
CREATE TABLE reports (id BIGINT PRIMARY KEY AUTO_INCREMENT, reporter_id BIGINT NOT NULL, target_type VARCHAR(20) NOT NULL, target_id BIGINT NOT NULL, reason VARCHAR(50) NOT NULL, details VARCHAR(1000), status VARCHAR(20) NOT NULL DEFAULT 'OPEN', reviewed_by BIGINT, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(reporter_id) REFERENCES users(id), FOREIGN KEY(reviewed_by) REFERENCES users(id));
CREATE TABLE notifications (id BIGINT PRIMARY KEY AUTO_INCREMENT, user_id BIGINT NOT NULL, type VARCHAR(50) NOT NULL, message VARCHAR(500) NOT NULL, reference_id BIGINT, is_read BOOLEAN NOT NULL DEFAULT FALSE, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(user_id) REFERENCES users(id));
CREATE TABLE moderation_logs (id BIGINT PRIMARY KEY AUTO_INCREMENT, actor_id BIGINT NOT NULL, target_type VARCHAR(30) NOT NULL, target_id BIGINT NOT NULL, action VARCHAR(50) NOT NULL, notes VARCHAR(1000), created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(actor_id) REFERENCES users(id));
CREATE TABLE post_tags (id BIGINT PRIMARY KEY AUTO_INCREMENT, post_id BIGINT NOT NULL, tag VARCHAR(50) NOT NULL, FOREIGN KEY(post_id) REFERENCES posts(id), UNIQUE(post_id,tag));
CREATE TABLE attachments (id BIGINT PRIMARY KEY AUTO_INCREMENT, post_id BIGINT NOT NULL, url VARCHAR(1000) NOT NULL, media_type VARCHAR(50) NOT NULL, FOREIGN KEY(post_id) REFERENCES posts(id));
